beforeExample:
package org.eclipse.jdt.internal.ui.typehierarchy;

import org.eclipse.jdt.core.IJavaElement;

public class MyClass {
    public void someMethod(IJavaElement[] elements) {
        String label = HistoryAction.getElementLabel(elements);
        System.out.println(label);
    }
}

class HistoryAction {
    public static String getElementLabel(IJavaElement[] elements) {
        return "History: " + elements.length;
    }
    public static String getSomeOtherLabel(Object o) {
        return "Other: " + o.hashCode();
    }
}

class TypeHierarchyViewPart {
    public static String getElementLabel(IJavaElement[] elements) {
        return "TypeHierarchy: " + elements.length;
    }
}

